export function findTaxonomySubject(name: string) {
  const n = (name || "").trim().toLowerCase()
  if (!n) return null
  return PYQ_TAXONOMY.find((s) => s.name.toLowerCase() === n) || null
}

export function findTaxonomyTopic(subjectName: string, topicNumOrName: string) {
  const sub = findTaxonomySubject(subjectName)
  if (!sub) return null
  const t = (topicNumOrName || "").trim().toLowerCase()
  if (!t) return null
  return (
    sub.topics.find((x) => x.num.toLowerCase() === t) ||
    sub.topics.find((x) => x.name.toLowerCase() === t) ||
    sub.topics.find((x) => (x.num + " " + x.name).toLowerCase() === t) ||
    null
  )
}

/** "Subject > Topic" text for the Copy-taxonomy-for-AI button. */
export function taxonomyListText() {
  return PYQ_TAXONOMY.map((s) =>
    [s.num + ". " + s.name, ...s.topics.map((t) => "  " + t.num + " " + t.name)].join("\n"),
  ).join("\n")
}
